module.exports = function(RED) {
    const sessionManager = require("../../runtime/session-manager").getInstance(RED);

    function SaveResponseNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.on('input', async function(msg) {
            const sessionId = msg.sessionId;
            const questionId = config.name || node.id;
            const answer = msg.payload || msg.dtmfDigits;

            if (sessionId && answer) {
                await sessionManager.saveResponse(sessionId, questionId, answer);
            }
            node.send(msg);
        });
    }
    RED.nodes.registerType("save-response", SaveResponseNode);
};